// HUD-004 first shell-only loader — OF-free tests for the PNG structural
// check (../src/HudSkinPng) and the loader state machine
// (../src/HudSkinLoader) against the ACCEPTED validator
// (tools/hud-skin-manifest/HudSkinManifest.cpp, unchanged). A fake image
// backend stands in for decode/upload so stage order, atomic activation,
// failed-replacement preservation and resource release are checked without a
// GL context; the real backend is exercised by SkinLoaderHarness.
//
// Fixture packages: skin_fixtures/skins/ (generated by
// skin_fixtures/make_skin_fixtures.py). The symlink cases are created at
// runtime in a scratch copy under $TMPDIR — the repository stores no symlinks.

#include "../src/HudSkinLoader.h"
#include "../src/HudSkinPng.h"

#include <filesystem>
#include <fstream>
#include <iostream>
#include <iterator>
#include <set>
#include <string>
#include <vector>

using namespace hudskin;
namespace fs = std::filesystem;

namespace {
int g_total = 0;
int g_failures = 0;
void reportFailure(const char* file, int line, const std::string& expr) {
	g_failures++;
	std::cerr << "FAIL " << file << ":" << line << ": " << expr << "\n";
}
} // namespace

#define HUD_CHECK(cond) \
	do { \
		g_total++; \
		if (!(cond)) reportFailure(__FILE__, __LINE__, #cond); \
	} while (0)

namespace {

const fs::path kFixtureRoot = fs::path(HUD_SKIN_TEST_FIXTURE_DIR) / "skins";

std::vector<uint8_t> readFile(const fs::path& p) {
	std::ifstream in(p, std::ios::binary);
	return std::vector<uint8_t>(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
}

PngStructureResult checkFile(const std::string& pkg) {
	auto bytes = readFile(kFixtureRoot / pkg / "shell.png");
	return checkPngStructure(bytes.data(), bytes.size());
}

// Fake backend: models the real backend's contract (nothing left allocated on
// failure; one texture per success) and records every handle it releases.
class FakeBackend : public ISkinImageBackend {
public:
	bool failDecode = false;
	bool failUpload = false;
	int stageCalls = 0;
	std::set<uint64_t> live;
	std::vector<uint64_t> released;

	SkinImageStageResult stageImage(const std::vector<uint8_t>& bytes, uint32_t w, uint32_t h) override {
		stageCalls++;
		SkinImageStageResult r;
		r.cpuPeakBytes = size_t(w) * h * 4;
		if (bytes.empty() || failDecode) {
			r.stage = SkinLoadStage::ImageDecode;
			r.code = loadcodes::DecodeFailed;
			r.detail = "fake decode failure";
			return r;
		}
		if (failUpload) {
			r.stage = SkinLoadStage::GpuUpload;
			r.code = loadcodes::UploadFailed;
			r.detail = "fake upload failure";
			return r;
		}
		r.ok = true;
		r.handle = next_++;
		r.gpuBytes = size_t(w) * h * 4;
		live.insert(r.handle);
		return r;
	}
	void release(uint64_t handle) override {
		live.erase(handle);
		released.push_back(handle);
	}
	size_t liveTextureCount() const override { return live.size(); }

private:
	uint64_t next_ = 100;
};

SkinLoaderConfig config(const fs::path& root) {
	SkinLoaderConfig c;
	c.skinsRoot = root;
	c.expectedBlueprint.expectedBlueprintId = "ecopunk-hud-blueprint";
	c.expectedBlueprint.expectedBlueprintVersion = 1u;
	return c;
}

constexpr size_t kShellBytes = size_t(1280) * 720 * 4;

// -- PNG structure -------------------------------------------------------------

void test_png_structure_fixtures() {
	auto a = checkFile("fixture-shell-proof");
	HUD_CHECK(a.ok && a.width == 1280 && a.height == 720 && a.bitDepth == 8 && a.colorType == 6);
	HUD_CHECK(checkFile("fixture-shell-proof-b").ok);
	HUD_CHECK(checkFile("not-png").code == pngcodes::SignatureInvalid);
	HUD_CHECK(checkFile("corrupt-png").code == pngcodes::CrcMismatch);
	HUD_CHECK(checkFile("truncated-png").code == pngcodes::Truncated);
	HUD_CHECK(checkFile("rgb-png").code == pngcodes::NotRgba8);
	HUD_CHECK(checkFile("gray-alpha-png").code == pngcodes::NotRgba8);
	HUD_CHECK(checkFile("indexed-png").code == pngcodes::NotRgba8);   // decoder would silently expand this
	HUD_CHECK(checkFile("sixteen-bit-png").code == pngcodes::NotRgba8);
	auto wrong = checkFile("wrong-size");
	HUD_CHECK(wrong.ok && wrong.width == 640 && wrong.height == 360); // size judged by the loader, not here
	// Structurally valid, broken zlib stream: passes here, must fail at decode.
	HUD_CHECK(checkFile("corrupt-stream").ok);
}

void test_png_structure_in_memory() {
	auto a = readFile(kFixtureRoot / "fixture-shell-proof" / "shell.png");
	HUD_CHECK(checkPngStructure(nullptr, 0).code == pngcodes::SignatureInvalid);
	HUD_CHECK(checkPngStructure(a.data(), 8).code == pngcodes::Truncated);
	auto trailing = a; trailing.push_back(0);
	HUD_CHECK(checkPngStructure(trailing.data(), trailing.size()).code == pngcodes::TrailingData);
	for (size_t cut : {size_t(12), size_t(33), a.size() - 1, a.size() - 12}) {
		auto r = checkPngStructure(a.data(), cut);
		HUD_CHECK(!r.ok && (r.code == pngcodes::Truncated || r.code == pngcodes::CrcMismatch));
	}
	// Every single-byte flip anywhere after the signature is detected (CRC / structure).
	int undetected = 0;
	for (size_t i = 8; i < a.size(); i += 97) {
		auto flipped = a;
		flipped[i] ^= 0x5A;
		if (checkPngStructure(flipped.data(), flipped.size()).ok) undetected++;
	}
	HUD_CHECK(undetected == 0);
}

// -- Rejection matrix (cold start, no active skin) ---------------------------------

struct Case { std::string selection; SkinLoadStage stage; std::string code; };

void test_cold_rejections_leave_wireframe() {
	FakeBackend backend;
	HudSkinLoader loader(backend);
	{
		auto o = loader.requestSkin("fixture-shell-proof");
		HUD_CHECK(!o.activated && o.code == loadcodes::NotConfigured);
	}
	loader.configure(config(kFixtureRoot));

	const Case cases[] = {
		{"", SkinLoadStage::Selection, loadcodes::NoSelection},
		{"../fixture-shell-proof", SkinLoadStage::Selection, loadcodes::SelectionInvalid},
		{"Fixture-Shell-Proof", SkinLoadStage::Selection, loadcodes::SelectionInvalid},
		{"does-not-exist", SkinLoadStage::PackageRoot, loadcodes::PackageNotFound},
		{"wrong-blueprint", SkinLoadStage::Manifest, codes::BlueprintIdMismatch},
		{"wrong-blueprint-version", SkinLoadStage::Manifest, codes::BlueprintVersionMismatch},
		{"path-escape", SkinLoadStage::Manifest, codes::PathParentTraversal},
		{"missing-shell", SkinLoadStage::Manifest, codes::PathNotFound},
		{"shell-undeclared", SkinLoadStage::Manifest, codes::AssetRequiredMissing},
		{"id-mismatch", SkinLoadStage::Manifest, loadcodes::SkinIdMismatch},
		{"decoration-declared", SkinLoadStage::Capability, loadcodes::UnsupportedClass},
		{"emissive-declared", SkinLoadStage::Capability, loadcodes::UnsupportedClass},
		{"not-png", SkinLoadStage::ImageStructure, pngcodes::SignatureInvalid},
		{"corrupt-png", SkinLoadStage::ImageStructure, pngcodes::CrcMismatch},
		{"truncated-png", SkinLoadStage::ImageStructure, pngcodes::Truncated},
		{"rgb-png", SkinLoadStage::ImageStructure, pngcodes::NotRgba8},
		{"gray-alpha-png", SkinLoadStage::ImageStructure, pngcodes::NotRgba8},
		{"indexed-png", SkinLoadStage::ImageStructure, pngcodes::NotRgba8},
		{"sixteen-bit-png", SkinLoadStage::ImageStructure, pngcodes::NotRgba8},
		{"wrong-size", SkinLoadStage::ImageStructure, loadcodes::ImageWrongSize},
	};
	for (const auto& c : cases) {
		auto o = loader.requestSkin(c.selection);
		bool ok = !o.activated && o.stage == c.stage && o.code == c.code && !o.activeSkinIdAfter && !o.retainedPreviousActive;
		HUD_CHECK(ok);
		if (!ok) std::cerr << "  (case '" << c.selection << "': stage=" << stageName(o.stage) << " code=" << o.code << ")\n";
	}
	HUD_CHECK(!loader.active().has_value());
	HUD_CHECK(backend.liveTextureCount() == 0);
	HUD_CHECK(backend.stageCalls == 0); // no rejected-before-decode candidate ever reached the backend

	// Unsupported-class rejection names the offending declaration.
	auto deco = loader.requestSkin("decoration-declared");
	HUD_CHECK(deco.asset == "assets.decoration");
	auto emi = loader.requestSkin("emissive-declared");
	HUD_CHECK(emi.asset == "assets.emissive");

	// Missing caller policy: the validator fails closed — no default identity.
	HudSkinLoader unset(backend);
	SkinLoaderConfig noPolicy;
	noPolicy.skinsRoot = kFixtureRoot;
	unset.configure(noPolicy);
	HUD_CHECK(unset.requestSkin("fixture-shell-proof").code == codes::PolicyBlueprintUnset);
}

void test_symlink_escapes() {
	const fs::path scratch = fs::temp_directory_path() / "hud_skin_loader_tests";
	std::error_code ec;
	fs::remove_all(scratch, ec);
	fs::create_directories(scratch / "root" / "symlink-escape");
	fs::create_directories(scratch / "outside");
	fs::copy_file(kFixtureRoot / "fixture-shell-proof" / "shell.png", scratch / "outside" / "shell.png");
	{
		std::ofstream m(scratch / "root" / "symlink-escape" / "skin.json");
		std::ifstream src(kFixtureRoot / "fixture-shell-proof" / "skin.json");
		std::string text((std::istreambuf_iterator<char>(src)), std::istreambuf_iterator<char>());
		auto pos = text.find("\"fixture-shell-proof\"");
		text.replace(pos, std::string("\"fixture-shell-proof\"").size(), "\"symlink-escape\"");
		m << text;
	}
	fs::create_symlink(scratch / "outside" / "shell.png", scratch / "root" / "symlink-escape" / "shell.png");
	fs::create_directory_symlink(kFixtureRoot / "fixture-shell-proof", scratch / "root" / "linked-package");

	FakeBackend backend;
	HudSkinLoader loader(backend);
	loader.configure(config(scratch / "root"));
	auto file = loader.requestSkin("symlink-escape");
	HUD_CHECK(!file.activated && file.stage == SkinLoadStage::Manifest && file.code == codes::PathSymlink);
	auto dir = loader.requestSkin("linked-package");
	HUD_CHECK(!dir.activated && dir.stage == SkinLoadStage::PackageRoot && dir.code == loadcodes::PackageNotFound);
	HUD_CHECK(backend.stageCalls == 0 && backend.liveTextureCount() == 0);
	fs::remove_all(scratch, ec);
}

// -- Activation, replacement, release -----------------------------------------------

void test_activation_replacement_and_release() {
	FakeBackend backend;
	HudSkinLoader loader(backend);
	loader.configure(config(kFixtureRoot));

	// Cold backend failures → still wireframe, nothing resident.
	backend.failDecode = true;
	auto d = loader.requestSkin("fixture-shell-proof");
	HUD_CHECK(!d.activated && d.stage == SkinLoadStage::ImageDecode && !d.activeSkinIdAfter);
	backend.failDecode = false;
	backend.failUpload = true;
	auto u = loader.requestSkin("fixture-shell-proof");
	HUD_CHECK(!u.activated && u.stage == SkinLoadStage::GpuUpload && u.code == loadcodes::UploadFailed && !u.activeSkinIdAfter);
	backend.failUpload = false;
	HUD_CHECK(backend.liveTextureCount() == 0 && !loader.active());

	// Valid cold load.
	auto a = loader.requestSkin("fixture-shell-proof");
	HUD_CHECK(a.activated && a.code == loadcodes::Activated && !a.hadActiveBefore && !a.releasedPrevious);
	HUD_CHECK(loader.active() && loader.active()->skinId == "fixture-shell-proof" && loader.active()->skinVersion == "0.0.1");
	HUD_CHECK(backend.liveTextureCount() == 1 && loader.steadyGpuBytes() == kShellBytes);
	const uint64_t handleA = loader.active()->handle;

	// Failed replacements: every stage keeps A active and leaves only A resident.
	for (const char* bad : {"corrupt-png", "wrong-blueprint", "decoration-declared", "does-not-exist", ""}) {
		auto o = loader.requestSkin(bad);
		HUD_CHECK(!o.activated && o.retainedPreviousActive && o.activeSkinIdAfter == std::string("fixture-shell-proof"));
	}
	backend.failUpload = true;
	auto up = loader.requestSkin("fixture-shell-proof-b");
	HUD_CHECK(!up.activated && up.stage == SkinLoadStage::GpuUpload && up.retainedPreviousActive);
	backend.failUpload = false;
	HUD_CHECK(loader.active()->handle == handleA && backend.liveTextureCount() == 1 && backend.released.empty());

	// Successful replacement: B active, A released, peak = A + B during staging.
	auto b = loader.requestSkin("fixture-shell-proof-b");
	HUD_CHECK(b.activated && b.hadActiveBefore && b.releasedPrevious && !b.retainedPreviousActive);
	HUD_CHECK(loader.active()->skinId == "fixture-shell-proof-b" && loader.active()->skinVersion == "0.0.2");
	HUD_CHECK(backend.released.size() == 1 && backend.released[0] == handleA);
	HUD_CHECK(backend.liveTextureCount() == 1);
	HUD_CHECK(b.peakGpuBytesDuringRequest == 2 * kShellBytes);
	HUD_CHECK(loader.steadyGpuBytes() == kShellBytes);
	HUD_CHECK(loader.lifetimePeakGpuBytes() == 2 * kShellBytes);

	// Reloading the SAME skin is a full candidate load and an atomic swap.
	const uint64_t handleB = loader.active()->handle;
	auto again = loader.requestSkin("fixture-shell-proof-b");
	HUD_CHECK(again.activated && again.releasedPrevious && loader.active()->handle != handleB);
	HUD_CHECK(backend.liveTextureCount() == 1);

	// Shutdown releases everything.
	loader.shutdown();
	HUD_CHECK(!loader.active() && backend.liveTextureCount() == 0 && loader.steadyGpuBytes() == 0);
	loader.shutdown(); // idempotent
	HUD_CHECK(backend.liveTextureCount() == 0);
}

void test_outcomes_are_deterministic() {
	FakeBackend b1, b2;
	HudSkinLoader l1(b1), l2(b2);
	l1.configure(config(kFixtureRoot));
	l2.configure(config(kFixtureRoot));
	for (const char* s : {"wrong-blueprint", "truncated-png", "fixture-shell-proof", "rgb-png", "fixture-shell-proof-b"}) {
		auto x = l1.requestSkin(s), y = l2.requestSkin(s);
		HUD_CHECK(x.activated == y.activated && x.stage == y.stage && x.code == y.code && x.detail == y.detail && x.asset == y.asset);
	}
}

} // namespace

int main() {
	test_png_structure_fixtures();
	test_png_structure_in_memory();
	test_cold_rejections_leave_wireframe();
	test_symlink_escapes();
	test_activation_replacement_and_release();
	test_outcomes_are_deterministic();

	std::cout << (g_total - g_failures) << "/" << g_total << " checks passed.\n";
	if (g_failures > 0) {
		std::cerr << g_failures << " FAILURE(S)\n";
		return 1;
	}
	return 0;
}
